import { BaseClassSrvc } from "@_core/__base";
import { FormBase } from "@_core/_form";

export function MyForm(that: BaseClassSrvc, d: any = {}) {
  that._fs._form = that._fb.group({
    ...FormBase(that, d),
    libraryId: [d?.libraryId || '', that._vs._val('Library')],
    cabinetId: [d?.cabinetId || '', that._vs._val('Cabinet')],
    shelfId: [d?.shelfId || '', that._vs._val('Shelf')],
    publisher: [d?.publisher || ''],
    author: [d?.author || ''],
  });
}
