import { BaseClassSrvc } from "@_core/__base";
import { FormBase } from "@_core/_form";

export function MyForm(that: BaseClassSrvc, d: any = {}) {
  that._fs._form = that._fb.group({
    ...FormBase(that, d),
    studentId: [d?.studentId || '', that._vs._val('Student')],
    libraryBookId: [d?.libraryBookId || '', that._vs._val('Book')],
    attendantId: [d?.attendantId || '', that._vs._val('Attendant')],
  });
}
